import {position,tilePosition,terrainHeight} from './geo.mjs';
import {dimensions,adjacent} from './grid.mjs';
import {climate} from './climate.mjs';
export const METRICS={
 condition:{label:'Infrastructure condition',unit:'%',range:[0,100],value:t=>t.condition??100},
 power:{label:'Electricity supply',unit:'%',range:[0,100],value:t=>t.powered?100:0},water:{label:'Water supply',unit:'%',range:[0,100],value:t=>t.watered?100:0},
 transit:{label:'Transit coverage',unit:'%',range:[0,100],value:t=>t.transit?100:0},pollution:{label:'Pollution index',unit:'/100',range:[0,100],value:t=>t.pollution||0},
 value:{label:'Land value',unit:'$',range:[25000,167500],value:t=>t.landPrice||0},population:{label:'Population heatmap',unit:'residents',range:[0,600],value:t=>t.population||0},density:{label:'Population hexagons',unit:'residents',range:[0,600],value:t=>t.population||0},
 traffic:{label:'Traffic & trips',unit:'% congestion',range:[0,100],value:t=>t.traffic||0},tax:{label:'Tax revenue',unit:'$/month',range:[0,600],value:t=>t.taxRevenue||0},building:{label:'Building value',unit:'$',range:[0,3e6],value:t=>t.buildingValue||0},
 surface:{label:'Surface temperature',unit:'°C',range:[-10,65],value:t=>t.surfaceTemp||0},air:{label:'Local air temperature',unit:'°C',range:[-10,45],value:t=>t.airTemp||0},carbon:{label:'Allocated operational CO₂',unit:'t/month',range:[0,50],value:t=>t.carbon||0},runoff:{label:'Runoff potential',unit:'%',range:[0,100],value:t=>(t.runoff||0)*100},load:{label:'Grid utilization proxy',unit:'%',range:[0,100],value:t=>t.cableLoad||0},parking:{label:'Parking occupancy',unit:'%',range:[0,100],value:t=>t.parkingCapacity?100*t.parkingUsed/t.parkingCapacity:0},wind:{label:'Wind & weather',unit:'km/h',range:[0,100],value:()=>0}
};
export const ANALYTICS={city:'City materials',...Object.fromEntries(Object.entries(METRICS).map(([k,v])=>[k,v.label]))};
const history=new WeakMap(),routes=new WeakMap();
export function captureAnalysis(city){let list=history.get(city);if(!list){list=[];history.set(city,list);}const last=list.at(-1);if(last?.month===city.month)list.pop();const values={};for(const [key,m]of Object.entries(METRICS))if(!['density','wind'].includes(key))values[key]=Float32Array.from(city.tiles,m.value);list.push({month:city.month,values});if(list.length>12)list.shift();return list;}
export const analysisHistory=city=>history.get(city)||[];
export function metricValue(city,t,key,snapshot=-1){if(key==='wind')return city.environment.wind;const past=snapshot>=0?analysisHistory(city)[snapshot]:null;return past?.values[key==='density'?'population':key]?.[t.id]??METRICS[key]?.value(t)??0;}
export function ramp(v){const a=[35,153,174],b=[100,224,177],c=[250,197,82],d=[243,89,81],x=Math.max(0,Math.min(1,v))*3,i=Math.min(2,Math.floor(x)),p=[a,b,c,d];return p[i].map((q,k)=>Math.round(q+(p[i+1][k]-q)*(x-i)));}
export function analyticColor(t,key,city,settings={}){if(!METRICS[key])return [176,192,194];const [lo,hi]=METRICS[key].range,v=city?metricValue(city,t,key,settings.snapshot):METRICS[key].value(t);const relative=(v-lo)/(hi-lo),outside=relative<(settings.min||0)/100||relative>(settings.max??100)/100;if(outside)return [91,109,114];const color=ramp(['power','water','transit'].includes(key)?1-relative:relative),mix=settings.opacity??1;return color.map((v,i)=>Math.round(v*mix+[172,185,183][i]*(1-mix)));}
export function eligible(t,key){if(['traffic','condition'].includes(key))return ['road','toll','bridge','bus','subway','elevatedStation'].includes(t.type);if(key==='parking')return ['parking','garage'].includes(t.type);if(['population','density','tax','carbon','building'].includes(key))return t.type!=='empty';if(['load','power'].includes(key))return t.wire||t.type!=='empty';if(key==='water')return t.pipe||t.type!=='empty';return t.terrain!=='water';}
export function roadRoutes(city){const cached=routes.get(city);if(cached?.revision===city.revision)return cached;const road=t=>['road','toll','bridge','bus','subway','elevatedStation'].includes(t.type),roads=(city.activeTiles||city.tiles).filter(road),paths=[];
 for(const start of roads.filter((_,i)=>i%4===0).slice(0,180)){const tiles=[start];let previous=-1,t=start;for(let step=0;step<14;step++){const next=adjacent(t.id,city).map(i=>city.tiles[i]).filter(n=>road(n)&&n.id!==previous);if(!next.length)break;previous=t.id;t=next[(start.id+step*13)%next.length];tiles.push(t);}if(tiles.length<2)continue;const path=tiles.map(t=>tilePosition(t,.5,.5,t.type==='bridge'?18.7:1.8,city));const duration=8+start.traffic*.15,offset=start.id%60;for(const cycle of [-1,0,1])paths.push({tileId:start.id,path,timestamps:tiles.map((_,i)=>offset+cycle*60+i*duration/(tiles.length-1)),traffic:start.traffic});}
 const entry={revision:city.revision,paths,roads};routes.set(city,entry);return entry;
}
export function analyticsLayers(city,key,{opacity=.68,min=0,max=100,radius=60,snapshot=-1,underground=false,cutDepth=45,onPick=()=>{}}={}){
 const {deck}=window,m=METRICS[key];if(!m||key==='wind')return [];const low=m.range[0]+(m.range[1]-m.range[0])*min/100,high=m.range[0]+(m.range[1]-m.range[0])*max/100,values=city.tiles.filter(t=>eligible(t,key)&&metricValue(city,t,key,snapshot)>=low&&metricValue(city,t,key,snapshot)<=high),pick=i=>{const id=i.object?.tileId??i.object?.id;if(Number.isInteger(id)){onPick(id);return true;}},color=t=>analyticColor(t,key,city,{snapshot});
 if(key==='population')return [new deck.HeatmapLayer({id:'population-heatmap',data:values,getPosition:t=>tilePosition(t,.5,.5,4,city),getWeight:t=>metricValue(city,t,key,snapshot),radiusPixels:radius,intensity:1.4,threshold:.03,opacity,parameters:{depthTest:false}})];
 if(key==='density'){
  const {cellSize}=dimensions(city),size=radius*2,bins=new Map();
  for(const t of values){const population=metricValue(city,t,key,snapshot);if(!population)continue;const px=(t.x+.5)*cellSize,py=(t.y+.5)*cellSize,q=(Math.sqrt(3)/3*px-py/3)/size,r=2*py/3/size;let rx=Math.round(q),rz=Math.round(r),ry=Math.round(-q-r);const dx=Math.abs(rx-q),dy=Math.abs(ry+q+r),dz=Math.abs(rz-r);if(dx>dy&&dx>dz)rx=-ry-rz;else if(dy>dz)ry=-rx-rz;else rz=-rx-ry;const id=`${rx}:${rz}`;if(!bins.has(id)){const x=size*Math.sqrt(3)*(rx+rz/2)/cellSize,y=size*1.5*rz/cellSize;bins.set(id,{tileId:t.id,position:position(x,y,terrainHeight(city,x,y)+1,city),population:0,count:0});}const bin=bins.get(id);bin.population+=population;bin.count++;}
  const data=[...bins.values()],peak=Math.max(1,...data.map(d=>d.population));return [new deck.ColumnLayer({id:'population-hexagons',data,diskResolution:6,angle:30,radius:size*.88,extruded:true,getPosition:d=>d.position,getElevation:d=>d.population*.15,getFillColor:d=>ramp(d.population/peak),opacity,pickable:true,onClick:pick,material:false})];
 }
 if(key==='traffic'){const valid=new Set(values.map(t=>t.id)),edges=[];for(const t of values)for(const id of adjacent(t.id,city))if(id>t.id&&valid.has(id)){const n=city.tiles[id];edges.push({tileId:t.id,path:[tilePosition(t,.5,.5,t.type==='bridge'?18.5:1.5,city),tilePosition(n,.5,.5,n.type==='bridge'?18.5:1.5,city)],color:color(t),value:metricValue(city,t,key,snapshot)});}return [new deck.PathLayer({id:'traffic-road-overlay',data:edges,getPath:d=>d.path,getColor:d=>d.color,getWidth:d=>4+d.value*.12,widthMinPixels:2,opacity,pickable:true,onClick:pick})];}
 const footprints=['building','tax','carbon','parking'].includes(key),polygons=values.map(t=>{const inset=footprints?.12:0;return {tileId:t.id,t,polygon:[[inset,inset],[1-inset,inset],[1-inset,1-inset],[inset,1-inset]].map(([x,y])=>position(t.x+x,t.y+y,terrainHeight(city,t.x+x,t.y+y)+(underground?-cutDepth+.5:1.2),city))};});
 return [new deck.PolygonLayer({id:'analysis-parcels',data:polygons,getPolygon:d=>d.polygon,getFillColor:d=>color(d.t),opacity,stroked:footprints,getLineColor:[223,247,237,120],getLineWidth:1,lineWidthUnits:'pixels',material:false,pickable:true,onClick:pick})];
}
export function animatedAnalytics(city,key,time,settings={},view={}){const {deck}=window,{animate=true,animationTime=0,animationSpeed=1,opacity=.68,min=0,max=100,snapshot=-1}=settings,clock=(animate?time*animationSpeed:animationTime)%60,layers=[],points=[];
 if(key==='traffic'){const trips=roadRoutes(city).paths.filter(p=>{const v=metricValue(city,city.tiles[p.tileId],key,snapshot);return v>=min&&v<=max;});layers.push(new deck.TripsLayer({id:'traffic-live-trips',data:trips,getPath:d=>d.path,getTimestamps:d=>d.timestamps,getColor:d=>ramp(d.traffic/100),getWidth:3,widthMinPixels:2,currentTime:clock,trailLength:4,fadeTrail:true,opacity,pickable:false}));}
 if(['power','water','load','transit'].includes(key)||view.underground){const network=view.underground?view.network:key==='water'?'pipe':key==='transit'?'tunnel':'wire',defs={wire:[3,[255,215,92],'wireLive'],pipe:[6,[88,212,255],'pipeLive'],tunnel:[18,[203,162,255],'metroLive'],drain:[35,[255,174,108],'drainLive']};for(const [name,[depth,color,live]]of Object.entries(defs)){if(network!=='all'&&network!==name||view.underground&&depth>view.cutDepth)continue;for(const t of city.activeTiles||city.tiles){if(!t[name]||!t[live])continue;for(const id of adjacent(t.id,city)){if(id<=t.id||!city.tiles[id][name]||!city.tiles[id][live])continue;const b=city.tiles[id],u=(clock*.25+(t.id%13)/13)%1,a=tilePosition(t,.5,.5,view.underground?-depth:4,city),z=tilePosition(b,.5,.5,view.underground?-depth:4,city);points.push({position:a.map((v,i)=>v+(z[i]-v)*u),color,radius:2.1});}}}}
 if(key==='wind'){const {width,height}=dimensions(city),paths=[],e=climate(city),cx=view.cameraGrid?.[0]??city.center?.[0]??width/2,cy=view.cameraGrid?.[1]??city.center?.[1]??height/2;for(let i=0;i<130;i++){const x=cx-22+((i*13.29+clock*e.wind*.035)%44),y=cy-18+(i*7.17)%36;if(x<0||y<0||x>=width||y>=height)continue;const h=terrainHeight(city,x,y)+50+(i%5)*12;paths.push({path:[position(x,y,h,city),position(x-1-e.wind*.015,y-.3,h,city)],color:[116,225,245,170]});}layers.push(new deck.PathLayer({id:'wind-live-streamlines',data:paths,getPath:d=>d.path,getColor:d=>d.color,getWidth:2,widthMinPixels:1.4,opacity,parameters:{depthMask:false}}));}
 if(points.length)layers.push(new deck.ScatterplotLayer({id:'utility-live-pulses',data:points,getPosition:d=>d.position,getFillColor:d=>d.color,getRadius:d=>d.radius,radiusMinPixels:2,opacity,parameters:{depthMask:false}}));return layers;
}
export function analyticsSummary(city,key,settings={}){const m=METRICS[key];if(!m)return '';const vals=city.tiles.filter(t=>eligible(t,key)).map(t=>metricValue(city,t,key,settings.snapshot)),lo=m.range[0]+(m.range[1]-m.range[0])*(settings.min||0)/100,hi=m.range[0]+(m.range[1]-m.range[0])*(settings.max??100)/100,shown=vals.filter(v=>v>=lo&&v<=hi);return `${shown.length.toLocaleString()} parcels · mean ${shown.length?(shown.reduce((a,b)=>a+b,0)/shown.length).toLocaleString('en-US',{maximumFractionDigits:1}):'—'} ${m.unit}`;}
